        '#link' => [
          '#type' => 'link',
          '#title' => $processDebugger->getEventLabel(),
          '#url' => Url::fromRoute('entity.eca.edit_with.nextgen_modeler', ['eca' => $processDebugger->getEcaId()], [
            'query' => [
              'select' => $processDebugger->getEventId(),
              'hash' => $hash,
