    }
    if ($propValue instanceof Attribute) {
      return (string) $propValue;
    }
    if (!is_array($propValue)) {
      return NULL;
    }
    $attributes = new Attribute($propValue);
    // Trim because Attribute::__toString() add a space on the left as it is
