    $paste = $this->htmxEvents->onClickPaste($paste, $builder_id, '__node_id__', '__parent_id__', '__slot_id__', '__slot_position__');

    return [
      $this->buildMenuItem($this->t('Copy'), 'copy'),
      $paste,
      $duplicate,
