      '#type' => 'select',
      '#title' => $this->t('Field'),
      '#description' => $this->t('Select view field to insert in this slot.'),
      '#options' => $options,
      '#default_value' => $this->getSetting('ui_patterns_views_field') ?? "",
      '#required' => TRUE,
