    if (isset($item["url"])) {
      return $item;
    }
    if (!isset($item["link"])) {
      return $item;
    }
    $item["url"] = $item["link"]["#url"];
    if (isset($item["link"]["#options"])) {
      $item["url"]->mergeOptions($item["link"]["#options"]);
    }
    unset($item["link"]);
    return $item;
  }

