      foreach ($toolkit->getRequirements() as $key => $requirement) {
        $namespaced_key = 'image.toolkit.' . $toolkit->getPluginId() . '.' . $key;
        $requirements[$namespaced_key] = $requirement;
      }
    }
    else {
      $requirements = [
        'image.toolkit' => [
          'title' => $this->t('Image toolkit'),
          'value' => $this->t('None'),
