  public function testQueryFetchColumn(): void {
    $statement = $this->connection
      ->query('SELECT [name] FROM {test} WHERE [age] = :age', [':age' => 25]);
    $statement->setFetchMode(FetchAs::Column, 0);
    $this->assertSame('John', $statement->fetch());
  }

