use Drupal\eb\Result\RollbackResult;
use Drupal\eb\Result\ValidationResult;

/**
 * Operation for creating Pathauto URL alias patterns.
 */
#[EbOperation(
  id: 'create_pathauto_pattern',
  label: new TranslatableMarkup('Create Pathauto Pattern'),
  description: new TranslatableMarkup('Creates a URL alias pattern for a bundle'),
  operationType: 'create',
)]
class CreatePathautoPatternOperation extends OperationBase {

  /**
   * {@inheritdoc}
   */
  public function validate(): ValidationResult {
    $result = new ValidationResult();

    // Validate required fields.
    $this->validateRequiredFields(
      ['entity_type', 'bundle', 'pattern', 'pattern_id'],
      $result
    );

    if (!$result->isValid()) {
      return $result;
    }

    $patternId = $this->getDataValue('pattern_id');
    $pattern = $this->getDataValue('pattern');

    // Validate pattern is not empty.
    if (empty(trim($pattern))) {
      $result->addError(
        $this->t('Pattern cannot be empty for pattern "@id".', ['@id' => $patternId]),
        'empty_pattern'
      );
    }

    return $result;
  }

  /**
   * {@inheritdoc}
   */
  public function preview(): PreviewResult {
    $patternId = $this->getDataValue('pattern_id');
    $entityType = $this->getDataValue('entity_type');
    $bundle = $this->getDataValue('bundle');
    $pattern = $this->getDataValue('pattern');
    $label = $this->getDataValue('label', '');

    $preview = new PreviewResult();

    // Check if updating or creating.
    $existing = $this->entityTypeManager
      ->getStorage('pathauto_pattern')
      ->load($patternId);

    $operation = $existing ? 'update' : 'create';

    $preview->addOperation(
      $operation,
      'pathauto_pattern',
      $patternId,
      $this->t('@op pathauto pattern "@label" for @entity_type.@bundle', [
        '@op' => $existing ? 'Update' : 'Create',
        '@label' => $label,
        '@entity_type' => $entityType,
        '@bundle' => $bundle,
      ])
    );

    $details = [
      'Pattern ID' => $patternId,
      'Entity Type' => $entityType,
      'Bundle' => $bundle,
      'Pattern' => $pattern,
    ];

    if (!empty($label)) {
      $details['Label'] = $label;
    }

    $preview->addDetails($details);

    return $preview;
  }

  /**
   * {@inheritdoc}
   */
  public function execute(): ExecutionResult {
    try {
      $patternId = $this->getDataValue('pattern_id');
      $entityType = $this->getDataValue('entity_type');
      $bundle = $this->getDataValue('bundle');
      $pattern = $this->getDataValue('pattern');
      $label = $this->getDataValue('label', "{$bundle} URL pattern");
      $weight = (int) $this->getDataValue('weight', 0);

      $storage = $this->entityTypeManager->getStorage('pathauto_pattern');

      // Check if pattern exists.
      $existingPattern = $storage->load($patternId);
      $wasExisting = $existingPattern !== NULL;
      $originalData = NULL;

      if ($existingPattern) {
        // Store original data for rollback.
        $originalData = [
          'pattern' => $existingPattern->getPattern(),
          'label' => $existingPattern->label(),
          'weight' => $existingPattern->getWeight(),
        ];

        // Update existing pattern.
        $existingPattern->setPattern($pattern);
        $existingPattern->set('label', $label);
        $existingPattern->setWeight($weight);
        $existingPattern->save();

        $result = new ExecutionResult(TRUE);
        $result->addMessage($this->t('Pathauto pattern "@label" updated successfully.', [
          '@label' => $label,
        ]));
      }
      else {
        // Create new pattern with bundle selection criteria.
        $patternEntity = $storage->create([
