      $context->expects($this->never())
        ->method('addViolation');
    }
    else {
      $context->expects($this->once())
        ->method('addViolation');
    }

    $constraint = new SerializedConstraint();

    $validate = new SerializedConstraintValidator();
    $validate->initialize($context);
    $validate->validate($value, $constraint);
  }

