#[CoversClass(FieldInputValueNormalizerTrait::class)]
#[Group('Field')]
class FieldInputValueNormalizerTraitTest extends UnitTestCase {

  use FieldInputValueNormalizerTrait;

  /**
   * Tests key value by delta.
   *
