    $parent_2 = $this->createTerm($this->vocabulary, [
      'langcode' => 'en',
      'moderation_state' => 'published',
      'parent' => $root->id(),
    ]);
    $parent_3 = $this->createTerm($this->vocabulary, [
      'langcode' => 'en',
      'moderation_state' => 'published',
      'parent' => $root->id(),
    ]);

    // Create a child term and assign one of the parents above.
    $child = $this->createTerm($this->vocabulary, [
      'langcode' => 'en',
      'moderation_state' => 'published',
      'parent' => $parent_1->id(),
    ]);

