    }
    if ((isset($form['value']['#pattern']) || isset($form['value']['#pattern_unicode'])) &&
        !isset($form['value']['#title'])) {
      $form['value']['#title'] = $this->propDefinition["title"] ?? $this->propId;
    }
    $form['value']["#description"] = implode("; ", $description);
